using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Demo5.FrontEnd;
public static class AlignGrowthContours {
 static SettlementFacilityFocus.Path Path(params float[] xy)=>new SettlementFacilityFocus.Path{Points=Enumerable.Range(0,xy.Length/2).Select(i=>new Vector2(xy[i*2],xy[i*2+1])).ToArray()};
 public static string Run(){const string path="Assets/Prefabs/Settlement/SettlementScreen.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var c=root.GetComponent<SettlementController>();var stock=c.Cabinet.GetComponent<SettlementFacilityFocus>();stock.UnrestoredPaths=new[]{Path(0,81,192,81,209,35,26,35)};var f=c.Development.ResearchButton.GetComponent<SettlementFacilityFocus>();var r=(RectTransform)f.transform;r.anchoredPosition=new Vector2(1020,-647);r.sizeDelta=new Vector2(208,115);f.Paths=new[]{Path(0,56,22,0,208,0,208,12,186,68,172,68,172,115,160,115,160,68,22,68,22,115,10,115,10,68,0,68)};PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();EditorSceneManager.OpenScene("Assets/Scenes/Settlement.unity");return "Temporary stock and completed desk match their own contour and click geometry.";}
}
